const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d'),dialog=$('dialog');
let selected=['lula','flavio'],selecting=0,mode='cpu',match=null,paused=false,sound=false,audioContext,last=0,accumulator=0,sceneTime=0,speechTimer=0,research={profiles:[]},shaking=0;
let photoCredits={photos:[]};fetch('photo-credits.json').then(r=>r.json()).then(v=>{photoCredits=v}).catch(()=>{});
const keys=new Set(),images=new Map();
function ensureSprite(id){if(images.has(id))return images.get(id);const image=new Image();image.src='assets/sprites/'+id+'.png?v=20261020-6';images.set(id,image);trimCast(images,[...selected,...(match?.fighters||[]).map(p=>p.data.id)]);return image}
selected.forEach(ensureSprite);
