const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function source(url,label='Abrir fonte ↗'){if(!url||!/^https:\/\//.test(url))return '';return `<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(label)}</a>`}
function beep(){soundscape.fx('ui')}
function toast(text){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.textContent=text;document.body.append(e);setTimeout(()=>e.remove(),3500)}
function renderRoster(){ $('roster').innerHTML=roster.map(f=>`<button class="fighter ${selected[0]===f.id?'selected-p1':''} ${selected[1]===f.id?'selected-p2':''}" data-fighter="${f.id}" aria-label="Selecionar ${f.name}" aria-pressed="${selected[selecting]===f.id}">${selected[0]===f.id?'<span class="player-badge">1P</span>':''}${selected[1]===f.id?'<span class="player-badge second">2P</span>':''}${portrait(f)}<span class="fighter-name">${f.short.toUpperCase()}</span></button>`).join('');renderCard(getFighter(selected[selecting]));
 document.querySelectorAll('[data-player]').forEach(b=>b.classList.toggle('active',+b.dataset.player===selecting));}
function renderCard(f){$('fighter-card').innerHTML=`<div class="portrait">${portrait(f)}</div><p class="eyebrow">${selecting===0?'SEU LUTADOR / 1P':'ADVERSÁRIO / 2P'}</p><h3>${f.name.toUpperCase()}</h3><p class="role">${f.style}</p>${[['VELOCIDADE',f.speed],['IMPACTO',f.power],['DEFESA',f.guard]].map(([n,v])=>`<div class="stat"><span>${n}</span><i><b style="width:${v*20}%"></b></i></div>`).join('')}<div class="move"><small>H · ESPECIAL / 25 BRASA · FICÇÃO</small><h4>${f.special.toUpperCase()}</h4><p>${f.specialDescription}</p><small>FINALIZAÇÃO</small><p>${f.fatal} — ${f.fatalDescription}</p></div><button id="preview-finisher">VER FINALIZAÇÃO ↗</button><button id="read-profile">HISTÓRICO, FALAS & POSIÇÕES ↗</button>`;$('preview-finisher').onclick=()=>openFinisherPreview(f.id);$('read-profile').onclick=()=>openResearch(f.id)}
function selectFighter(id){selected[selecting]=id;ensureSprite(id);renderRoster();beep(410,.04);if(match&&match.state!=='result'){toast('Lutador selecionado para a próxima partida.');return}renderHUD();}
$('roster').addEventListener('click',e=>{const b=e.target.closest('[data-fighter]');if(b)selectFighter(b.dataset.fighter)});
document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{selecting=+b.dataset.player;renderRoster()});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(e=>e.classList.toggle('active',e===b));$('opponent-label').textContent=mode==='local'?'2P':mode==='training'?'TREINO':'CPU';if(match)toast('Modo alterado para a próxima partida.');});
$('random').onclick=()=>selectFighter(roster[Math.floor(Math.random()*roster.length)].id);
function showSpeech(index,real=false){const f=match.fighters[index].data,p=research.profiles.find(p=>p.id===f.id),quote=real?(p?.debateQuote||p?.quote):null;if(quote){$('speech-label').textContent=`${f.name.toUpperCase()} · FALA REAL · ${quote.date} · CONTEXTO NO DOSSIÊ`;$('speech-text').textContent=`“${quote.text}”`;}else{$('speech-label').textContent=`${f.name.toUpperCase()} · PARÓDIA / FALA FICTÍCIA`;$('speech-text').textContent=f.quip}$('speech').classList.remove('hidden');speechTimer=quote?6:3;}
function event(type,data={}){if(type==='finisher-cue')soundscape.fx(data.phase===2?'super':data.phase===1?'whoosh':'pickup');if(type==='attack'){soundscape.fx('whoosh');if(data.kind==='special'||data.kind==='super')soundscape.fx(data.kind)}if(type==='hit'||type==='hurt'){soundscape.fx(data.kind==='kick'?'kick':'hit',data.damage?data.damage/14:1);if(!reducedMotion())shaking=.12}if(type==='block')soundscape.fx('block');if(type==='jump')soundscape.fx('jump');if(type==='land')soundscape.fx('land',(data.speed||500)/650);if(type==='step')soundscape.fx('step');if(type==='break')soundscape.fx('break');if(type==='pickup')soundscape.fx('pickup');if(type==='speech')showSpeech(data.real?(match.round-1)%2:data.index,data.real);if(type==='dry'&&data.index===0)toast('Sem Brasa suficiente. Acerte ou receba golpes para carregar.');if(type==='fatal'){soundscape.fx('fatal');$('speech').classList.add('hidden')}if(type==='finish'){keys.clear();$('speech').classList.add('hidden')}}
function start(onlineDifficulty=null){soundscape.unlock(true);selected.forEach(ensureSprite);match=new Match(getFighter(selected[0]),getFighter(selected[1]),mode,event,Math.random,{difficulty:onlineDifficulty||preferences.difficulty});paused=false;keys.clear();$('welcome').classList.add('hidden');$('overlay').classList.add('hidden');$('speech').classList.add('hidden');speechTimer=0;canvas.focus();renderHUD();}
$('start').onclick=()=>{if(network.guest){toast('O criador inicia a partida.');return}start()};
function setText(id,text){const el=$(id);if(el.textContent!==text)el.textContent=text}
function renderHUD(){const fs=match?.fighters,ms=match?.mode||mode;for(let i=0;i<2;i++){const p='p'+(i+1),f=fs?.[i];setText(p+'-name',(f?.data||getFighter(selected[i])).name.toUpperCase());$(p+'-health').style.width=(f?.hp??100)+'%';$(p+'-meter').style.width=(f?.meter??25)+'%';setText(p+'-wins',[0,1].map(n=>(match?.wins[i]||0)>n?'●':'○').join(' '))}setText('timer',ms==='training'&&match?'∞':String(Math.ceil(match?.timer??60)).padStart(2,'0'));setText('round','ROUND '+String(match?.round??1).padStart(2,'0'));setText('opponent-label',ms==='local'?'2P':ms==='training'?'TREINO':'CPU');setText('status',paused?'DEBATE SUSPENSO':!match?'PRONTO PARA O CONFRONTO':match.state==='fight'?'AO VIVO · COMBATE EM ANDAMENTO':match.state==='finish'?'ACABOU O SEU TEMPO':match.state==='result'?'DEBATE ENCERRADO':'DIREITO DE RESPOSTA');}
let overlayKey='';
function overlays(){const state=!match?'welcome':paused?'paused':match.state,key=state+(match?.round||0)+(match?.sequence.length||0);if(key===overlayKey)return;overlayKey=key;const overlay=$('overlay');if(['welcome','fight','fatal'].includes(state)){overlay.classList.add('hidden');return}overlay.classList.remove('hidden');let kicker='',title='',description='',buttons='';
 if(state==='intro'){kicker=`MELHOR DE 3 · ${match.mode==='training'?'TREINO LIVRE':'DIREITO DE RESPOSTA'}`;title=`ROUND ${match.round}`;description='Prepare seu argumento.'}
 if(state==='paused'){kicker='INTERVALO COMERCIAL';title='DEBATE SUSPENSO';description='Pressione ESC para continuar.';buttons='<button data-action="resume">CONTINUAR ↗</button><button data-action="restart">RECOMEÇAR</button><button data-action="menu">SELECIONAR ELENCO</button>'}
 if(state==='roundover'){kicker='ACABOU O TEMPO DE RESPOSTA';title=match.winner===null?'EMPATE':match.fighters[match.winner].data.short.toUpperCase()+' LEVOU O ROUND';description='O próximo bloco começa em instantes.'}
 if(state==='finish'){const f=match.fighters[match.winner];kicker='ÚLTIMO DIREITO DE RESPOSTA';title='FINALIZE O DEBATE';description=`${f.data.short}: ${f.data.fatal}. ${match.winner===0?'S → '+(f.facing===1?'D':'A')+' → S → T':match.mode==='cpu'?'A CPU prepara sua finalização…':'↓ → '+(f.facing===1?'→':'←')+' → ↓ → I (ou Num 0)'} · ${match.sequence.length}/4`;buttons='<button data-action="skip">ENCERRAR SEM FATALITY</button>'}
 if(state==='result'){const f=match.fighters[match.winner];kicker='RESULTADO DO CONFRONTO';title=f?f.data.short.toUpperCase()+' VENCEU':'DEBATE ENCERRADO';description=f?`Placar ${match.wins[0]} × ${match.wins[1]} · ${f.data.quip}`:'';buttons='<button data-action="restart">REVANCHE ↗</button><button data-action="menu">SELECIONAR ELENCO</button>'}
 $('overlay-kicker').textContent=kicker;$('overlay-title').textContent=title;$('overlay-description').textContent=description;$('overlay-actions').innerHTML=buttons;
}
$('overlay-actions').addEventListener('click',e=>{const a=e.target.dataset.action;if(a==='resume'){paused=false;network.control(false);canvas.focus()}if(a==='restart'&&!network.guest)start();if(a==='menu'){if(network.active)network.leave();match=null;paused=false;keys.clear();$('welcome').classList.remove('hidden');$('overlay').classList.add('hidden');$('speech').classList.add('hidden');document.querySelector('.selection').scrollIntoView({behavior:reducedMotion()?'instant':'smooth'})}if(a==='skip'){match.state='result';match.stateTime=0}});
function pause(){if(match&&match.state!=='result'){paused=!paused;network.control(paused);keys.clear()}}
const actions={KeyF:[0,'punch'],KeyG:[0,'kick'],KeyH:[0,'special'],KeyR:[0,'super'],Numpad1:[1,'punch'],Numpad2:[1,'kick'],Numpad3:[1,'special'],Numpad5:[1,'super'],KeyJ:[1,'punch'],KeyK:[1,'kick'],KeyL:[1,'special'],KeyU:[1,'super']};
const gameKeys=new Set(['KeyW','KeyA','KeyS','KeyD','KeyF','KeyG','KeyH','KeyR','KeyT','KeyJ','KeyK','KeyL','KeyU','KeyI','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Numpad0','Numpad1','Numpad2','Numpad3','Numpad5','Enter','Escape']);
window.addEventListener('keydown',event=>{const code=canonicalCode(event),e={code,repeat:event.repeat,target:event.target,preventDefault:()=>event.preventDefault()};if(dialog.open||document.querySelector('.settings-dialog[open]'))return;if(!gameKeys.has(e.code)||e.target.matches('input,textarea,select'))return;if(!match&&e.code!=='Enter')return;if(e.code==='Enter'&&e.target.closest('button,a'))return;e.preventDefault();if(e.repeat)return;keys.add(e.code);if(e.code==='Enter'&&!match){start();return}if(e.code==='Escape'){pause();return}if(!match||paused)return;
 if(network.guest){if(match.state==='finish'){const f=match.fighters[1],key=e.code==='KeyS'?'down':e.code===(f.facing===1?'KeyD':'KeyA')?'forward':e.code==='KeyT'?'fatal':null;if(key)network.send({type:'finish',key})}else{const action=actions[e.code];if(action?.[0]===0)network.action(action[1])}return}if(match.state==='finish'){for(let i=0;i<2;i++){if(i===1&&match.mode!=='local')continue;const f=match.fighters[i],key=i===0?(e.code==='KeyS'?'down':e.code===(f.facing===1?'KeyD':'KeyA')?'forward':e.code==='KeyT'?'fatal':null):(e.code==='ArrowDown'?'down':e.code===(f.facing===1?'ArrowRight':'ArrowLeft')?'forward':(e.code==='Numpad0'||e.code==='KeyI')?'fatal':null);if(key)match.finishKey(i,key)}return}
 const a=actions[e.code];if(a&&(a[0]===0||match.mode==='local'))match.attack(...a);
});
window.addEventListener('keyup',e=>keys.delete(canonicalCode(e)));
window.addEventListener('brasa:modal',()=>{keys.clear();if(match)paused=true});
window.addEventListener('blur',()=>{keys.clear();if(match&&match.state!=='result')paused=true;network.control(true)});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(match&&match.state!=='result')paused=true;network.control(true)}});
function inputs(){return [{left:keys.has('KeyA'),right:keys.has('KeyD'),down:keys.has('KeyS'),jump:keys.has('KeyW')},{left:keys.has('ArrowLeft'),right:keys.has('ArrowRight'),down:keys.has('ArrowDown'),jump:keys.has('ArrowUp')}]}
function drawFatal(){const winner=match.fighters[match.winner],loser=match.fighters[1-match.winner];const drawActor=(c,f,x,y)=>{c.save();c.translate(x,y-510);drawFighter(c,{...f,x:0},ensureSprite(f.data.id),sceneTime,290);c.restore()};drawFinisherScene(ctx,{winner,loser,progress:1-match.stateTime/FINISHER_DURATION,reduced:reducedMotion(),drawWinner:drawActor,drawLoser:drawActor})}
const FLOOR=510;
function draw(){$('arena').classList.toggle('cinematic',match?.state==='fatal');ctx.save();if(shaking>0&&!reducedMotion())ctx.translate((Math.random()-.5)*8,(Math.random()-.5)*5);drawStage(ctx,sceneTime);const fs=match?.fighters||[getFighter(selected[0]),getFighter(selected[1])].map((data,index)=>({data,index,x:index?1000:280,y:0,vx:0,stun:0,block:false,shield:0,facing:index?-1:1}));for(const f of match?.state==='fatal'?[]:fs)drawFighter(ctx,f,images.get(f.data.id),sceneTime);
 if(match){for(const p of match.projectiles){ctx.save();ctx.translate(p.x,FLOOR-p.y);ctx.shadowColor=p.color;ctx.shadowBlur=24;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(0,0,p.radius,0,7);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff0bf';ctx.font=`bold ${p.radius}px Arial`;ctx.textAlign='center';ctx.fillText(p.symbol,0,p.radius*.35);ctx.restore()}for(const e of match.effects){ctx.save();ctx.globalAlpha=Math.min(1,e.life*5);ctx.fillStyle=e.color;ctx.strokeStyle=e.color;if(e.type==='hit'){ctx.translate(e.x,e.y);for(let i=0;i<8;i++){ctx.rotate(Math.PI/4);ctx.fillRect(12,0,22,4)}}else if(e.type==='area'){ctx.fillStyle=e.color+'55';ctx.fillRect(e.x-60,200,120,310);ctx.strokeRect(e.x-60,200,120,310)}else if(e.type==='pixel'){ctx.fillRect(e.x,e.y,12,12)}ctx.restore()}
  for(const f of match.fighters)if(f.combo>=2){ctx.fillStyle='#f6cd82';ctx.font='800 italic 28px "Barlow Condensed",Arial';ctx.textAlign=f.index?'right':'left';ctx.fillText(`${f.combo} HITS`,f.index?1160:120,160)}
  if(match.state==='fatal')drawFatal();
 }ctx.restore();updateGameView(match?.state==='fatal'?[]:fs.map(f=>f.x));}
function frame(timestamp){recordFrame(timestamp);soundscape.setRunning(!!match&&!paused&&!dialog.open);const dt=Math.min((timestamp-last)/1000||0,.1);last=timestamp;sceneTime+=paused?0:dt;shaking=Math.max(0,shaking-dt);if(network.guest){network.input(inputs()[0]);network.interpolate(match,dt)}if(match&&!paused&&!dialog.open&&!network.guest){accumulator+=dt;while(accumulator>=1/60){match.update(1/60,network.host?[inputs()[0],network.remote()]:inputs());accumulator-=1/60}speechTimer-=dt;if(speechTimer<=0)$('speech').classList.add('hidden')}else accumulator=0;network.publish(match,paused);draw();renderHUD();overlays();requestAnimationFrame(frame)}
function openDialog(label,html){if(match&&match.state!=='result')paused=true;keys.clear();$('dialog-label').textContent=label;$('dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal()}
function controls(){openDialog('STREET BRASA / MANUAL DE COMBATE',`<h2>SEU DIREITO DE RESPOSTA.</h2><p>Melhor de três rounds de 60 segundos. Vença dois rounds para abrir a janela de finalização. No celular, use os controles de toque e gire para paisagem.</p><div class="controls-grid">${[[1,[['Mover','W A S D'],['Soco','F'],['Chute','G'],['Especial · 25 Brasa','H'],['Super · 100 Brasa','R'],['Defender','S'],['Fatality','S → D/A → S → T']]],[2,[['Mover','↑ ← ↓ →'],['Soco','J / Numpad 1'],['Chute','K / Numpad 2'],['Especial · 25 Brasa','L / Numpad 3'],['Super · 100 Brasa','U / Numpad 5'],['Defender','↓'],['Fatality','↓ → Frente → ↓ → I (ou Num 0)']]]].map(([n,rows])=>`<div><h3>JOGADOR ${n}</h3>${rows.map(([n,k])=>`<div class="key-row"><span>${n}</span><span>${escape(k)}</span></div>`).join('')}</div>`).join('')}</div><h3>OS ESPECIAIS</h3><p>Projétil: atinge à distância e pode ser evitado com um salto. Avanço: fecha a distância com um ataque. Ascendente: alcança o rival no ar. Área: marca o chão e explode após um breve aviso. Escudo: reduz o dano por dois segundos. O super lança um projétil de alta potência.</p><h3>A ÚLTIMA RESPOSTA</h3><p>Ao vencer a partida, pressione baixo, frente, baixo e fatality, soltando cada tecla antes da próxima. No celular, toque ↓, depois a direção do rival, ↓ e FINALIZAR. Você tem sete segundos. “Frente” é a direção do adversário. A CPU também pode finalizar. Cada personagem tem uma cena e um nome de finalização.</p><p>ESC pausa. A partida pausa automaticamente ao sair da janela. No treino, o adversário fica parado e recupera a vida quando ela chega ao mínimo. O jogador 2 usa J, K, L e U, com I para finalizar; também pode usar o teclado numérico com Num Lock ativo. Alguns teclados limitam teclas simultâneas no versus local.</p>`)}
function openResearch(id=selected[selecting]){const f=getFighter(id),p=research.profiles.find(p=>p.id===id),photo=photoCredits.photos.find(p=>p.id===id);openDialog('STREET BRASA / DOSSIÊ DO ELENCO',`<h2>POR TRÁS DO PERSONAGEM.</h2><p>Histórico, posições e falas públicas, pesquisados em 20/10/2026. Fontes partidárias registram as posições dos próprios autores. As citações foram conferidas em textos publicados; áudio e timestamps ainda não foram conferidos.</p><div class="research-nav">${roster.map(r=>`<button data-profile="${r.id}" class="${id===r.id?'active':''}">${r.short}</button>`).join('')}</div><article class="research-body">${photo?`<div class="research-photo">${portrait(f,true)}<div><span class="tag">${photo.redistributed===false?'REFERÊNCIA EXTERNA · RECONSTRUÇÃO NO JOGO':'FOTOGRAFIA DE REFERÊNCIA'}</span><p>${escape(photo.credit)} · ${escape(photo.license)}</p>${source(photo.sourcePage,'Origem da fotografia ↗')}<p>${escape(photo.notes)}</p><p>${photo.redistributed===false?'A fotografia original está disponível apenas na fonte externa. A imagem exibida foi reconstruída por IA.':'Retrato documental; corpo e poses de combate reconstruídos por IA.'} Cenas fictícias.</p></div></div>`:''}<span class="tag">PERFIL PÚBLICO / ${f.style.toUpperCase()}</span><h3>${f.name.toUpperCase()}</h3>${p?`<p>${escape(p.history)}</p>${(p.historySources||[]).map(s=>source(s.url,s.titulo||'Referência biográfica ↗')).join(' · ')}<h3>POSIÇÕES & ATUAÇÃO PÚBLICA</h3><ul>${p.positions.map(v=>`<li><strong>${escape(v.date)} · ${escape(v.period)}</strong><br>${escape(v.text)}<br>${source(v.url,v.title||'Fonte do registro ↗')}</li>`).join('')}</ul>${p.quote?`<div class="source-block"><span class="tag">FALA REAL · ${escape(p.quote.date)}</span><blockquote>“${escape(p.quote.text)}”</blockquote><p>${escape(p.quote.context)}</p>${source(p.quote.url)}</div>`:'<p>Sem fala literal verificada para este perfil.</p>'}${p.debateQuote?`<div class="source-block"><span class="tag">FALA REAL / DEBATE BAND · 18/10/2026</span><blockquote>“${escape(p.debateQuote.text)}”</blockquote><p>${escape(p.debateQuote.context)}</p>${source(p.debateQuote.url)}</div>`:''}<h3>DO PERFIL PARA O ARCADE</h3><p>Referências criativas: ${escape((p.motifs||[]).join(' · '))}. O especial <strong>${f.special}</strong> e a finalização <strong>${f.fatal}</strong> são interpretações fictícias, sem atribuição de atos reais ao personagem.</p>${p.notes?.length?`<h3>CONTEXTO & LIMITES</h3><ul>${p.notes.map(n=>`<li>${escape(n)}</li>`).join('')}</ul>`:''}`:`<p>${research.error?'Não foi possível carregar o dossiê. Recarregue a página.':'Carregando pesquisa… feche e abra este painel em instantes.'}</p>`}<h3>O DEBATE QUE INSPIROU A ARENA</h3><p>O cenário é uma reconstrução visual por IA baseada em fotografia real do estúdio da Band de 23/08/2026, usada como referência para a arena inspirada no debate presidencial de 18/10/2026. Não é uma fotografia daquele encontro de outubro. As falas de outros períodos estão identificadas com sua data e não são apresentadas como parte daquele debate.</p>${source('https://www.band.com.br/politica/eleicoes/ao-vivo-assista-ao-debate-na-band-entre-flavio-bolsonaro-e-lula','Band · íntegra e contexto ↗')}<p>A playlist enviada não pôde ser consultada; nenhum documento foi anexado. O dossiê reúne fontes públicas pesquisadas. Paródia independente, sem vínculo com emissoras, partidos ou franquias de jogos. Violência estilizada; indicação de 16 anos é sugestão editorial, sem classificação oficial.</p></article>`);$('dialog-content').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{openResearch(b.dataset.profile)})}
document.querySelectorAll('[data-dialog]').forEach(b=>b.onclick=()=>b.dataset.dialog==='controls'?controls():openResearch());$('close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{keys.clear();canvas.focus()});
$('sound').onclick=()=>{sound=!sound;$('sound').setAttribute('aria-pressed',sound);$('sound').innerHTML=sound?'SOM ON <span>◉</span>':'SOM OFF <span>◌</span>';beep(550,.1,'triangle')};
installGameDisplay();
